 <div class="indicator-admin-side">
  <?php if($isAdministrator):?><form class="content-card indicator-config-form" method="post" action="/admin/indicators/target"><input type="hidden" name="_csrf" value="<?=$h($csrf)?>"><input type="hidden" name="indicator_id" value="<?=(int)$selected['id']?>"><header><div><h2>Nova versão de meta</h2><p>A vigência anterior é encerrada automaticamente.</p></div></header><div class="target-fields"><label><span>Operador</span><select class="bh-field bh-select" name="target_operator"><?php foreach($operators as$v=>$label):?><option value="<?=$v?>"><?=$label?></option><?php endforeach;?></select></label><label><span>Valor</span><input class="bh-field" name="target_value" inputmode="decimal" placeholder="Ex.: 90 ou 5.5e10" required></label><label><span>Vigente desde</span><input class="bh-field" type="date" name="effective_from" value="<?=date('Y-m-01')?>" required></label></div><button class="button">Salvar nova meta</button></form><?php endif;?>
