<script>
(()=>{const bind=(dialog,triggers,fill)=>{triggers.forEach(button=>button.addEventListener('click',()=>{fill(dialog,button);dialog.showModal();document.body.classList.add('modal-open')}));dialog.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>dialog.close()));dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));};
bind(document.getElementById('removeResponsibleDialog'),document.querySelectorAll('.responsible-remove'),(d,b)=>{d.querySelector('[name=user_id]').value=b.dataset.userId;d.querySelector('#removeResponsibleName').textContent=b.dataset.userName});
bind(document.getElementById('editTargetDialog'),document.querySelectorAll('.target-edit'),(d,b)=>{d.querySelector('[name=target_id]').value=b.dataset.id;d.querySelector('[name=target_operator]').value=b.dataset.operator;d.querySelector('[name=target_value]').value=b.dataset.value;d.querySelector('[name=effective_from]').value=b.dataset.effective});
bind(document.getElementById('deleteTargetDialog'),document.querySelectorAll('.target-delete'),(d,b)=>{d.querySelector('[name=target_id]').value=b.dataset.id;d.querySelector('#deleteTargetLabel').textContent=b.dataset.label;d.querySelector('#deleteTargetEffective').textContent=b.dataset.effective;d.querySelector('[name=deletion_reason]').value=''});})();
</script>
